class.description:
Classe statique (non instanciable) : appeler directement [code]SaveManager.save(...)[/code]. Chaque opération utilise le [method SaveData.get_system_id] comme nom de fichier et la [SaveConfig] passée en argument pour le dossier et l'extension ; en général, celle du [SaveData] lui-même.
Le résultat est écrit dans la console (succès en vert, échec en rouge, sauvegarde absente en jaune) avec l'icône du module.
[codeblock]
var options := SaveData.new()
options.set_system_id("options")
options.set_is_encrypted(false)

func enregistrer(volume: float) -> void:
	options.get_data()["volume"] = volume
	SaveManager.save(options, options.get_file_config())

func charger() -> float:
	var relu := SaveManager.load(options, options.get_file_config())
	return relu.get_data().get("volume", 1.0) if relu else 1.0
[/codeblock]
